-- 1. Plan Upgraded
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0001-4000-8000-000000000001', 'Upgrade de Plano Confirmado', 'Email enviado quando usuario faz upgrade do plano', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A00E5 0%,#6B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Upgrade Confirmado!</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Seu plano foi atualizado com sucesso para <strong>{{nome_plano}}</strong>! Agora voce tem acesso a todos os recursos inclusos no novo plano.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;text-align:center;"><p style="color:#16a34a;font-size:14px;font-weight:600;margin:0;">Novo Plano</p><p style="color:#15803d;font-size:24px;font-weight:700;margin:8px 0;">{{nome_plano}}</p><p style="color:#16a34a;font-size:16px;margin:0;">{{valor_fatura}}/{{ciclo_cobranca}}</p></td></tr></table><p style="color:#4a4a4a;font-size:16px;line-height:1.7;">Recursos desbloqueados:</p><ul style="color:#4a4a4a;font-size:15px;line-height:2;margin:0 0 20px;padding-left:20px;"><li>Todos os modulos Omni, Flow, Track e Suite</li><li>Envio ilimitado de emails e WhatsApp</li><li>Agentes de IA personalizados</li><li>Rastreamento avancado de documentos</li></ul><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Explorar Meu Novo Plano</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 2. Subscription Renewed
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0002-4000-8000-000000000002', 'Assinatura Renovada', 'Email enviado quando assinatura e renovada automaticamente', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A00E5 0%,#6B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Assinatura Renovada</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Sua assinatura do plano <strong>{{nome_plano}}</strong> foi renovada automaticamente com sucesso!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f7ff;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 0;color:#666;font-size:14px;">Plano</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;font-weight:600;">{{nome_plano}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Valor</td><td style="padding:8px 0;color:#3A00E5;font-size:18px;text-align:right;font-weight:700;">{{valor_fatura}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Proxima renovacao</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{proxima_cobranca}}</td></tr></table></td></tr></table><p style="color:#4a4a4a;font-size:16px;line-height:1.7;">Continue aproveitando todos os recursos do Ellosuit!</p><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Acessar Dashboard</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 3. Payment Failed / Retry
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0003-4000-8000-000000000003', 'Falha no Pagamento', 'Email enviado quando cobranca falha', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#dc2626 0%,#ef4444 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Falha no Pagamento</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Nao conseguimos processar o pagamento da sua assinatura. Isso pode acontecer por saldo insuficiente, cartao expirado ou limite excedido.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#fef2f2;border:1px solid #fecaca;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><p style="color:#991b1b;font-size:14px;margin:0 0 8px;font-weight:600;">O que fazer:</p><ul style="color:#7f1d1d;font-size:14px;line-height:2;margin:0;padding-left:20px;"><li>Verifique se seu cartao esta valido</li><li>Confira o limite disponivel</li><li>Tente atualizar o metodo de pagamento</li></ul></td></tr></table><p style="color:#4a4a4a;font-size:14px;line-height:1.6;margin:0 0 20px;">Tentaremos cobrar novamente em 3 dias. Se o pagamento nao for regularizado, seu acesso podera ser suspenso.</p><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#dc2626,#ef4444);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Atualizar Pagamento</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 4. Subscription Canceled by User
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0004-4000-8000-000000000004', 'Cancelamento Confirmado', 'Email enviado quando usuario cancela assinatura', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#6b7280 0%,#9ca3af 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Cancelamento Confirmado</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Confirmamos o cancelamento da sua assinatura do plano <strong>{{nome_plano}}</strong>. Sentiremos sua falta!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f3f4f6;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><p style="color:#4b5563;font-size:14px;margin:0 0 8px;">Voce ainda tem acesso ate:</p><p style="color:#1f2937;font-size:20px;font-weight:700;margin:0;">{{proxima_cobranca}}</p><p style="color:#6b7280;font-size:13px;margin:8px 0 0;">Apos essa data, sua conta voltara ao plano gratuito.</p></td></tr></table><p style="color:#4a4a4a;font-size:16px;line-height:1.7;">Seus dados serao mantidos por 90 dias. Voce pode reativar a qualquer momento e recuperar tudo.</p><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online/dashboard/assinatura" style="display:inline-block;background:linear-gradient(135deg,#3A00E5,#6B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Reativar Minha Assinatura</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 5. New Contact Registered (CRM)
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0005-4000-8000-000000000005', 'Novo Contato Cadastrado', 'Email de confirmacao quando novo contato entra no CRM', 'crm',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#FF4500 0%,#FF6B35 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Cadastro Recebido!</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Recebemos seu cadastro com sucesso! Agora voce faz parte da nossa base de contatos e em breve entraremos em contato com mais informacoes.</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;">Agradecemos seu interesse!</p><p style="text-align:center;margin:32px 0;"><a href="https://www.ellosuit.online" style="display:inline-block;background:linear-gradient(135deg,#FF4500,#FF6B35);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Conhecer o Ellosuit</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 6. Meeting Scheduled
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0006-4000-8000-000000000006', 'Reuniao Agendada', 'Email enviado quando uma reuniao e agendada via booking link', 'agendamento',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#007DE3 0%,#3B9AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Reuniao Confirmada</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Sua reuniao foi agendada com sucesso!</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 0;color:#666;font-size:14px;">Titulo</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;font-weight:600;">{{titulo_reuniao}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Data</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{data_reuniao}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Horario</td><td style="padding:8px 0;color:#007DE3;font-size:18px;text-align:right;font-weight:700;">{{horario_reuniao}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Duracao</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{duracao_reuniao}}</td></tr></table></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="{{link_reuniao}}" style="display:inline-block;background:linear-gradient(135deg,#007DE3,#3B9AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Entrar na Reuniao</a></p><p style="color:#888;font-size:13px;text-align:center;">Adicione este evento ao seu calendario para nao esquecer!</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

