INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0007-4000-8000-000000000007', 'Lembrete de Reuniao', 'Lembrete enviado 30 min antes da reuniao', 'agendamento',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#f59e0b 0%,#d97706 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Sua Reuniao Comeca em Breve!</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Este e um lembrete de que sua reuniao <strong>{{titulo_reuniao}}</strong> comeca em 30 minutos.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#fffbeb;border:1px solid #fde68a;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;text-align:center;"><p style="color:#92400e;font-size:32px;font-weight:700;margin:0;">{{horario_reuniao}}</p><p style="color:#b45309;font-size:14px;margin:8px 0 0;">{{data_reuniao}}</p></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="{{link_reuniao}}" style="display:inline-block;background:linear-gradient(135deg,#f59e0b,#d97706);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Entrar Agora</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

