INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0008-4000-8000-000000000008', 'Documento Compartilhado', 'Email enviado quando documento/proposta e compartilhado', 'documentos',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A9A1C 0%,#4CAF50 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Documento Compartilhado</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Um documento foi compartilhado com voce:</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;text-align:center;"><p style="color:#15803d;font-size:18px;font-weight:600;margin:0;">{{nome_documento}}</p><p style="color:#16a34a;font-size:14px;margin:8px 0 0;">Enviado por {{nome_remetente}}</p></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="{{link_documento}}" style="display:inline-block;background:linear-gradient(135deg,#3A9A1C,#4CAF50);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Abrir Documento</a></p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 9. Proposal / Service Order Sent
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0009-4000-8000-000000000009', 'Proposta Enviada', 'Email enviado quando proposta/OS e enviada ao cliente', 'documentos',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3000E3 0%,#5B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Nova Proposta</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Segue em anexo a proposta <strong>{{numero_proposta}}</strong> referente aos servicos solicitados.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f7ff;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 0;color:#666;font-size:14px;">Proposta</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;font-weight:600;">{{numero_proposta}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Valor Total</td><td style="padding:8px 0;color:#3000E3;font-size:18px;text-align:right;font-weight:700;">{{valor_proposta}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Validade</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">{{validade_proposta}}</td></tr></table></td></tr></table><p style="text-align:center;margin:32px 0;"><a href="{{link_proposta}}" style="display:inline-block;background:linear-gradient(135deg,#3000E3,#5B3AFF);color:#ffffff;text-decoration:none;padding:16px 40px;border-radius:8px;font-size:16px;font-weight:600;">Ver Proposta Completa</a></p><p style="color:#888;font-size:13px;line-height:1.6;text-align:center;">Em caso de duvidas, responda este email.</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

-- 10. Refund Processed
INSERT INTO public.email_templates (id, name, description, category, html_content, is_active, user_id, company_id) VALUES
('b1000001-0010-4000-8000-000000000010', 'Reembolso Processado', 'Email de confirmacao de reembolso', 'financeiro',
'<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f4f4;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f4f4;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#3A00E5 0%,#6B3AFF 100%);padding:40px 40px 30px;text-align:center;"><img src="https://ellosuit-connect-vista.lovable.app/images/ellosuit-logo.png" alt="Ellosuit" width="180" style="display:inline-block;max-width:180px;height:auto;filter:brightness(0) invert(1);"></td></tr><tr><td style="padding:40px;"><h1 style="color:#1a1a1a;font-size:28px;margin:0 0 16px;text-align:center;">Reembolso Processado</h1><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Ola <strong>{{nome_cliente}}</strong>,</p><p style="color:#4a4a4a;font-size:16px;line-height:1.7;margin:0 0 20px;">Seu reembolso foi processado com sucesso. O valor sera creditado em sua conta em ate 10 dias uteis.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;margin:24px 0;"><tr><td style="padding:24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:8px 0;color:#666;font-size:14px;">Valor Reembolsado</td><td style="padding:8px 0;color:#16a34a;font-size:18px;text-align:right;font-weight:700;">{{valor_fatura}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">ID Transacao</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;font-family:monospace;">{{id_transacao}}</td></tr><tr><td style="padding:8px 0;color:#666;font-size:14px;">Prazo</td><td style="padding:8px 0;color:#1a1a1a;font-size:14px;text-align:right;">Ate 10 dias uteis</td></tr></table></td></tr></table><p style="color:#888;font-size:13px;line-height:1.6;text-align:center;">Em caso de duvidas sobre o reembolso, entre em contato conosco.</p></td></tr><tr><td style="background-color:#f9f9f9;padding:24px 40px;text-align:center;border-top:1px solid #eee;"><p style="color:#888;font-size:12px;margin:0;">2025 Ellosuit. Todos os direitos reservados.</p></td></tr></table></td></tr></table></body></html>',
true, 'c63ba931-0c34-4461-ae8d-2908aed7dd20', '60008c43-e536-482d-a090-91904de57534');

